w": true, "required": false}, "itemoptions": {"style": {"marginBottom": "14px"}}}, {"field": "FilterPageSettingId", "type": "settingSelect", "labeloptions": {"label": "筛选配置Id", "show": true, "required": false}, "itemoptions": {"style": {"marginBottom": "14px"}}}, {"field": "ListPageSettingId", "type": "settingSelect", "labeloptions": {"label": "列表配置Id", "show": true, "required": false}, "itemoptions": {"style": {"marginBottom": "14px"}}}, {"field": "DetailPageSettingId", "type": "settingSelect", "labeloptions": {"label": "详情/编辑配置Id", "show": true, "required": false}, "itemoptions": {"style": {"marginBottom": "14px"}}}]}', '免Model CRUD外壳：TableName 自动推导 dyndata 接口；可引用 Filter/List/Detail PageSetting 三屏配置', 1, 1);